DO $$ DECLARE d text;BEGIN SELECT pg_get_functiondef('public.assign_to_authorization(uuid,text,text,uuid,uuid)'::regprocedure) INTO d;d:=replace(d,'IF p_kind=''position'' THEN IF p_person IS NULL','IF p_kind=''position'' THEN IF EXISTS(SELECT 1 FROM time_entries WHERE personnel_id=p_person AND location_id=o.location_id AND (is_locked OR invoice_id IS NOT NULL) AND clock_out_at>start_at) THEN RAISE EXCEPTION ''Locked or invoiced source cannot be reassigned'';END IF; IF NOT EXISTS(SELECT 1 FROM location_assignments a WHERE a.location_id=o.location_id AND a.personnel_id=p_person AND lower(COALESCE((SELECT rr.role_label FROM location_assignment_roles rr WHERE rr.assignment_id=a.id AND rr.effective_from<=GREATEST(start_at,a.assigned_at) ORDER BY rr.effective_from DESC LIMIT 1),a.role_label))=lower(p_label)) THEN RAISE EXCEPTION ''Allocation role must match the dated location role'';END IF; IF p_person IS NULL');d:=replace(d,'ELSE IF p_kind<>''asset'' OR p_asset IS NULL','ELSE IF NOT EXISTS(SELECT 1 FROM asset_assignments aa JOIN assets ax ON ax.id=aa.asset_id WHERE aa.id=p_asset AND lower(ax.type)=lower(p_label)) THEN RAISE EXCEPTION ''Allocation asset type must match the authorized line'';END IF; IF p_kind<>''asset'' OR p_asset IS NULL');EXECUTE d;END $$;
CREATE FUNCTION public.guard_to_sheet_header() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF EXISTS(SELECT 1 FROM location_to_sheet_entries WHERE sheet_id=OLD.id) THEN RAISE EXCEPTION 'Signed sheet requirements are immutable';END IF;IF TG_OP='DELETE' THEN RETURN OLD;END IF;RETURN NEW;END $$;REVOKE ALL ON FUNCTION public.guard_to_sheet_header() FROM PUBLIC,anon,authenticated;CREATE TRIGGER to_signed_sheet_header BEFORE UPDATE OR DELETE ON public.location_to_sheets FOR EACH ROW EXECUTE FUNCTION public.guard_to_sheet_header();